Widget recipesPage(BuildContext context,LocalStore store)=>RecordList(title:'Meine Rezepte',kind:'recipe',store:store,subtitle:(r)=>'${str(r['category'])} · ${r['template']==true?'Leere Vorlage':'Version ${r['version']}'}',edit:(r)async{await openPage(context,RecipeEditor(store:store,initial:r));},detail:(r)async{await openPage(context,RecipeDetail(store:store,recipeId:str(r['id'])));});
class RecipeEditor extends StatefulWidget{
  final LocalStore store;final Json? initial;
  const RecipeEditor({super.key,required this.store,this.initial});
  @override State<RecipeEditor> createState()=>_RecipeEditorState();
}
class _RecipeEditorState extends State<RecipeEditor>{
  final form=GlobalKey<FormState>();late Json data={'baseKg':1.0,'loss':0.0,...?widget.initial};late List<Json> lines=maps(data['lines']);late Json process=map(data['process']);late List<String> images=strings(data['images']);bool busy=false;
  void change(){if(mounted)setState((){});}
  Future<void> addImage()async{await guarded(context,()async{final bytes=await LocalFiles.pick('image/*');if(bytes==null)return;if(bytes.length>1024*1024){if(mounted)toast(context,'Bild maximal 1 MB nach Verkleinerung. Bitte kleineres Bild wählen.');return;}final saved=await widget.store.save('recipeImage',{'name':'Rezeptfoto','encoded':base64Encode(bytes)});if(mounted)setState(()=>images.add(str(saved['id'])));});}
  Future<void> save()async{if(busy||!(form.currentState?.validate()??false))return;setState(()=>busy=true);await guarded(context,()async{await widget.store.save('recipe',{...data,'lines':lines,'process':process,'images':images,'template':lines.isEmpty});if(mounted)Navigator.pop(context,true);});if(mounted)setState(()=>busy=false);}
  @override Widget build(BuildContext context){final meat=lines.where((l)=>l['materialKind']=='meat').toList();final meatKg=meat.fold(0.0,(s,l)=>s+(convert(n(l['quantity']),str(l['unit']),'kg')??0));return PageFrame(title:widget.initial==null?'Neues Rezept':'Rezept bearbeiten',child:Form(key:form,child:ListView(padding:const EdgeInsets.all(12),children:[Section('Rezeptdaten',[Fields(specs:[const FieldSpec('name','Produktname / Variante',required:true),FieldSpec('category','Kategorie',choices:widget.store.recipeCategories,required:true),const FieldSpec('baseKg','Bezugsmenge Fleisch/Speck (kg)',required:true,number:true,min:0.001),const FieldSpec('loss','Erwarteter Gewichtsverlust (%)',number:true,min:0,max:99.999,required:true),const FieldSpec('description','Beschreibung',multiline:true)],data:data,changed:change)]),Section('Rezeptur',[const Notice('Mengen für die oben gewählte Bezugsmenge eingeben. Gewürze können in g erfasst werden. Für Zutaten pro kg bei 1 kg Bezugsmenge direkt g/kg eingeben. Freie Positionen sind ebenfalls möglich.'),LinesEditor(lines:lines,store:widget.store,changed:change,recipe:true),if(meatKg>0)...[const Divider(),ValueRow('Fleisch-/Specksumme','${fmt(meatKg)} kg'),for(final l in meat)ValueRow(nameOf(l),'${fmt((convert(n(l['quantity']),str(l['unit']),'kg')??0)/meatKg*100,2)} %'),if((meatKg-n(data['baseKg'])).abs()>0.001)const Notice('Bezugsmenge und erfasste Fleischsumme weichen ab. Bewusst prüfen.',icon:Icons.warning_amber)] ]),Section('Herstellung & Lagerung',[Fields(specs:[for(final entry in processFields.entries)FieldSpec(entry.key,entry.value,multiline:['instructions','notes','storage','packaging'].contains(entry.key))],data:process,changed:change)]),Section('Produktbilder',[if(images.isEmpty)const Text('Noch keine Bilder.'),for(var i=0;i<images.length;i++)Row(children:[Expanded(child:recipeImage(widget.store,images[i],110)),IconButton(onPressed:(){setState(()=>images.removeAt(i));},icon:const Icon(Icons.delete_outline))]),OutlinedButton.icon(onPressed:images.length>=8?null:addImage,icon:const Icon(Icons.photo_library),label:const Text('Bild lokal auswählen'))]),FilledButton.icon(onPressed:busy?null:save,icon:const Icon(Icons.save),label:const Text('Rezept speichern')),const SizedBox(height:24)])));}
}
class RecipeDetail extends StatefulWidget{
  final LocalStore store;final String recipeId;
  const RecipeDetail({super.key,required this.store,required this.recipeId});
  @override State<RecipeDetail> createState()=>_RecipeDetailState();
}
class _RecipeDetailState extends State<RecipeDetail>{
  Json quantity={};
  @override Widget build(BuildContext context)=>AnimatedBuilder(animation:widget.store,builder:(context,_) {
    final r=widget.store.get('recipe',widget.recipeId);if(r==null)return const PageFrame(title:'Rezept',child:EmptyState('Rezept nicht vorhanden.'));
    quantity.putIfAbsent('kg',()=>n(r['baseKg']));final base=n(r['baseKg']);final kg=numOrNull(quantity['kg']);final scale=kg!=null&&kg>0&&base>0?kg/base:0.0;final lines=scaledRecipeLines(r,widget.store,scale);final process=map(r['process']);final versions=widget.store.all('recipeVersion').where((v)=>v['recipeId']==r['id']).toList()..sort((a,b)=>n(b['version']).compareTo(n(a['version'])));
    final total=lines.every((l)=>lineCost(l)!=null)?lines.fold(0.0,(s,l)=>s+lineCost(l)!):null;
    return PageFrame(title:nameOf(r),actions:[IconButton(tooltip:'Bearbeiten',onPressed:()=>openPage(context,RecipeEditor(store:widget.store,initial:r)),icon:const Icon(Icons.edit)),PopupMenuButton<String>(onSelected:(action)async{if(action=='duplicate'){await guarded(context,()async{final copy={...r}..remove('id')..remove('created')..remove('updated');copy['name']='${nameOf(r)} – Kopie';copy['archived']=false;final saved=await widget.store.save('recipe',copy);if(context.mounted)await openPage(context,RecipeEditor(store:widget.store,initial:saved));});}else{await guarded(context,()async{await LocalFiles.report(nameOf(r),[('Kategorie / Version','${str(r['category'])} / ${str(r['version'])}'),('Bezugsmenge','${fmt(kg??0)} kg'),('Rezeptur',lines.map((l)=>'${nameOf(l)}: ${fmt(n(l['quantity']))} ${str(l['unit'])}').join('\n')),for(final e in process.entries)if(str(e.value).isNotEmpty)(processFields[e.key]??e.key,str(e.value)),('Hinweis','Rezeptdaten ohne fachliche Freigabe.')]);});}},itemBuilder:(_)=>const [PopupMenuItem(value:'duplicate',child:Text('Duplizieren')),PopupMenuItem(value:'pdf',child:Text('PDF exportieren'))])],child:ListView(padding:const EdgeInsets.all(12),children:[if(r['template']==true)const Notice('Leere Rezeptvorlage. Über Bearbeiten die eigene Rezeptur eintragen.'),Text('${str(r['category'])} · Version ${str(r['version'])}'),if(str(r['description']).isNotEmpty)Text(str(r['description'])),for(final photo in strings(r['images']))Padding(padding:const EdgeInsets.only(top:8),child:recipeImage(widget.store,photo,160)),Section('Mengen umrechnen',[Fields(specs:const [FieldSpec('kg','Gewünschte Bezugsmenge (kg)',number:true,min:0.001)],data:quantity,changed:()=>setState((){})),if(scale<=0)const Notice('Positive Bezugsmenge eingeben.'),for(final l in lines)ValueRow(nameOf(l),'${fmt(n(l['quantity']))} ${str(l['unit'])}'),const Divider(),ValueRow('Positionskosten (aktuelle Stammdaten)',shownMoney(lines.isEmpty?null:total),strong:true),if(lines.any((l)=>l['materialId']!=null&&!widget.store.materials.any((m)=>m['id']==l['materialId'])))const Notice('Archivierte/fehlende Stammdaten: gespeicherte Preise werden verwendet. Bitte kontrollieren.')]),FilledButton.icon(onPressed:scale>0&&lines.isNotEmpty?()=>openPage(context,CalculationPage(store:widget.store,recipe:r,recipeKg:kg)):null,icon:const Icon(Icons.calculate),label:const Text('Kosten & Gewinn berechnen')),OutlinedButton.icon(onPressed:scale>0&&lines.isNotEmpty?()=>openPage(context,CalculationPage(store:widget.store,recipe:r,recipeKg:kg,production:true)):null,icon:const Icon(Icons.factory_outlined),label:const Text('Produktion erfassen')),OutlinedButton.icon(onPressed:()=>openPage(context,QualityPage(store:widget.store,recipe:r,lines:lines)),icon:const Icon(Icons.fact_check_outlined),label:const Text('Qualitätsprüfung')),Section('Herstellung',[for(final e in process.entries)if(str(e.value).isNotEmpty)ValueRow(processFields[e.key]??e.key,str(e.value)),if(process.values.every((v)=>str(v).isEmpty))const Text('Noch keine Herstellungsangaben.')]),if(versions.isNotEmpty)Section('Versionshistorie',[for(final v in versions)ListTile(contentPadding:EdgeInsets.zero,title:Text('Version ${str(v['version'])}'),subtitle:Text(dateLabel(v['updated'])),trailing:const Icon(Icons.chevron_right),onTap:()=>openPage(context,PageFrame(title:'Rezeptversion ${str(v['version'])}',child:ListView(padding:const EdgeInsets.all(16),children:[Text(nameOf(v)),ValueRow('Kategorie',str(v['category'])),ValueRow('Bezugsmenge','${fmt(n(v['baseKg']))} kg'),for(final l in maps(v['lines']))ValueRow(nameOf(l),'${fmt(n(l['quantity']))} ${str(l['unit'])}'),for(final e in map(v['process']).entries)if(str(e.value).isNotEmpty)ValueRow(processFields[e.key]??e.key,str(e.value)),FilledButton(onPressed:()async{if(await confirm(context,'Version übernehmen?','Die alte Version wird als neue Rezeptversion gespeichert.')){await widget.store.save('recipe',{...map(v['snapshot']),'id':r['id'],'archived':false});if(context.mounted)Navigator.pop(context);}},child:const Text('Als neue Version übernehmen'))]))))]) ]));});
}

Widget recipeImage(LocalStore store,String imageId,double height){try{final encoded=str(store.get('recipeImage',imageId)?['encoded']);return Image.memory(base64Decode(encoded),height:height,fit:BoxFit.contain,errorBuilder:(_,__,___)=>const Text('Bild nicht lesbar'));}catch(_){return const Text('Bild nicht lesbar');}}
